def max_of_list(lst):
    if not lst:
        return None  # Якщо список пустий, повертаємо None

    max_value = lst[0]  # Починаємо з першого елемента як мінімального

    for num in lst:
        if num > max_value:
            max_value = num  # Оновлюємо максимальне значення, якщо знайдено більше число

    return max_value

